const JEE_AUTHORITY = 'National Testing Agency (NTA)';
const JEE_CHECK = '2026-10-06';
const JEE_SITE = 'https://jeemain.nta.nic.in';
const JEE_FILES = 'https://cdnbbsr.s3waas.gov.in/s3f8e59f4b2fe7c5705bf878bbd494ccdf/uploads/';
