// ==========================================================================
// mockPapersData.ts
// ==========================================================================
export interface MockPaper {
  id: string;
  title: string;
  category: 'FULL_SHIFT' | 'SUBJECT_TEST' | 'TOPIC_DRILL' | 'SECTIONAL_MOCK' | 'CUSTOM_AI';
  examTier: 'Tier-1' | 'Tier-2';
  subject?: string;
  topic?: string;
  year?: number;
  shiftDate?: string;
  totalQuestions: number;
  totalMarks: number;
  durationMinutes: number;
  difficulty: 'EASY' | 'MEDIUM' | 'HARD' | 'ADAPTIVE';
  description: string;
  provenanceTag: string;
  questions: PracticeQuestion[];
  /** Plain-language notes about how a custom test was assembled (off-syllabus topics, generated vs bank). */
  generationNotes?: string[];
  /** One-line restatement of the request the generator acted on. */
  requestSummary?: string;
  /** Marks for a right and off for a wrong answer, with the clause that sets them. Every paper states
   *  its own: there is no default, so a paper of any exam is never scored by another exam's rule. */
  marking: PaperMarking;
}

export interface PaperMarking { correct: number; wrong: number; clause: string }

/** Para 13.8.2 of the SSC CGL 2026 notice, with 2 marks a question (Para 13.8). */
export const SSC_TIER1_MARKING: PaperMarking = {
  correct: 2, wrong: 0.5, clause: 'Tier-I: 2 marks a question; 0.50 off for each wrong answer (Para 13.8.2)'
};

/** Words that rank a paper against other papers. A paper may state its own level (`difficulty`, checked
 *  against its own questions) but never call itself harder or easier than another. */
const RELATIVE_DIFFICULTY_CLAIM = /\b(harder|hardest|easier|easiest|tougher|toughest|stiffer|more difficult|less difficult|harder mix|easier mix)\b/i;

/**
 * What a practice paper's metadata may claim, for any exam and any number of papers: everything it says
 * about itself must follow from its own questions and its own marking. Returns the problems found
 * (empty = consistent). Used by the checks over every paper GovOS holds; a new exam's papers are held
 * to the same rules with no change here.
 */
export function mockPaperProblems(paper: MockPaper): string[] {
  const problems: string[] = [];
  const m = paper.marking;
  if (!m || !(m.correct > 0) || !(m.wrong >= 0) || !m.clause) problems.push('marking: missing, or without its clause');
  if (paper.totalQuestions !== paper.questions.length) problems.push(`totalQuestions ${paper.totalQuestions} but ${paper.questions.length} questions`);
  if (m && m.correct > 0 && paper.totalMarks !== paper.questions.length * m.correct) {
    problems.push(`totalMarks ${paper.totalMarks} but ${paper.questions.length} x ${m.correct}`);
  }
  if (new Set(paper.questions.map(q => q.id)).size !== paper.questions.length) problems.push('question ids repeat');
  const claim = `${paper.title} ${paper.description}`.match(RELATIVE_DIFFICULTY_CLAIM);
  if (claim) problems.push(`claims "${claim[0]}" relative to other papers`);
  if (paper.difficulty !== 'ADAPTIVE') {
    const counts: Record<string, number> = {};
    for (const q of paper.questions) counts[q.difficulty] = (counts[q.difficulty] || 0) + 1;
    const top = Math.max(0, ...Object.values(counts));
    if ((counts[paper.difficulty] || 0) !== top) {
      problems.push(`labelled ${paper.difficulty} but its questions are ${JSON.stringify(counts)}`);
    }
  }
  return problems;
}

export interface CustomTestConfig {
  title?: string;
  selectedSubjects: string[];
  selectedTopics: string[];
  numQuestions: number;
  difficulty: 'EASY' | 'MEDIUM' | 'HARD' | 'ADAPTIVE';
  focusGoal?: 'GENERAL' | 'WEAK_AREAS' | 'SPEED_BOOSTER' | 'PRE_EXAM';
  /** Explicit timer requested by the candidate, in minutes. Overrides calibration. */
  durationMinutes?: number;
}

/** A practice question with no named source: GovOS wrote it; it is not an SSC question. */
const sscProvenance: DataProvenance = {
  id: 'prov-ssc-cgl-practice',
  documentTitle: 'GovOS practice question — not from an SSC paper',
  officialUrl: '',
  publishedDate: '',
  verifiedDate: '',
  verifiedBy: 'Written by GovOS; not an official question',
  taxonomyType: 'RECOMMENDATION',
  verificationLevel: 'UNDER_VERIFICATION',
  excerptText: 'GovOS wrote this question for practice. It is not taken from an SSC question paper or answer key, and SSC has not reviewed it.'
};

/**
 * Provenance for a practice question. GovOS reads the official document and writes the
 * question and worked solution from it; it never redistributes the document itself.
 */
export interface QuestionSource {
  /** Human-readable citation, e.g. "NCERT Exemplar Class 10 Maths, Triangles, Exercise 6.1 Q2". */
  label: string;
  /** Public URL of the official document the question was written from. */
  url: string;
  /** Publishing authority. */
  publisher: string;
  /** GOVOS_AUTHORED marks a question written by GovOS rather than taken from an official exercise. */
  kind: 'OFFICIAL_EXERCISE' | 'OFFICIAL_DOCUMENT' | 'GOVOS_AUTHORED';
}

// ncert.nic.in refuses connections from many Indian networks. NCERT's own upload of this
// book on the Internet Archive (creator: NCERT, collection: ncert-textbooks) serves the
// identical chapter files under the same file codes, and it opens.
// Reader URL: archive.org/details/ncert-jeep2/<file> opens that chapter in the in-browser
// viewer (no save dialog). The direct PDF is archive.org/download/ncert-jeep2/<file>.pdf.
const NCERT_X_MATHS = 'https://archive.org/details/ncert-jeep2/';
const NCERT_X_MATHS_PDF = 'https://archive.org/download/ncert-jeep2/';
const NCERT_X_MATHS_CANONICAL = 'https://ncert.nic.in/pdf/publication/exemplarproblem/classX/mathematics/';
const CONSTITUTION_PDF = 'https://www.legislative.gov.in/static/uploads/2025/07/c9fe9c9b6840524844316f74bb1c556c.pdf';
const SSC_NOTICE_2026 = 'https://ssc.gov.in/api/attachment/uploads/masterData/NoticeBoards/Notice_of_adv_cgl_2026.pdf';

const ncertSource = (chapterPdf: string, citation: string): QuestionSource => ({
  label: citation,
  url: NCERT_X_MATHS + chapterPdf.replace(/\.pdf$/, ''),
  publisher: `National Council of Educational Research and Training (NCERT) — opens in the Internet Archive reader for NCERT's own upload; direct PDF: ${NCERT_X_MATHS_PDF}${chapterPdf}; canonical file: ${NCERT_X_MATHS_CANONICAL}${chapterPdf}`,
  kind: 'OFFICIAL_EXERCISE'
});

const constitutionSource = (citation: string): QuestionSource => ({
  label: citation,
  url: CONSTITUTION_PDF,
  publisher: 'Legislative Department, Ministry of Law & Justice',
  kind: 'OFFICIAL_DOCUMENT'
});

const sscNoticeSource = (citation: string): QuestionSource => ({
  label: citation,
  url: SSC_NOTICE_2026,
  publisher: 'Staff Selection Commission (SSC)',
  kind: 'OFFICIAL_DOCUMENT'
});

/** Practice question written by GovOS. Not lifted from an official paper. */
const govosSource = (citation: string): QuestionSource => ({
  label: citation,
  // The pattern it was written to: the notice's scheme and syllabus, not the homepage.
  url: SSC_NOTICE_URL,
  publisher: 'GovOS Preparation Team (pattern based on the official SSC syllabus)',
  kind: 'GOVOS_AUTHORED'
});

